changeSet.sql:
CREATE TABLE stop_factors.stop_factor_metric ( id BIGINT NOT NULL, created_date TIMESTAMP(6), updated_date TIMESTAMP(6), root_id BIGINT, version_number INTEGER NOT NULL DEFAULT 1, valid_from TIMESTAMP(6) NOT NULL, valid_to TIMESTAMP(6), change_reason VARCHAR(255), created_by VARCHAR(255), title VARCHAR(255) NOT NULL, calculator VARCHAR(64) NOT NULL, name_template TEXT NOT NULL, params JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT true, CONSTRAINT pk_stop_factor_metric PRIMARY KEY (id), CONSTRAINT fk_stop_factor_metric_root FOREIGN KEY (root_id) REFERENCES stop_factors.stop_factor_metric (id), CONSTRAINT ck_stop_factor_metric_root CHECK ((root_id IS NULL) = (version_number = 1)), CONSTRAINT ck_stop_factor_metric_version_number CHECK (version_number >= 1), CONSTRAINT ck_stop_factor_metric_validity CHECK (valid_to IS NULL OR valid_to >= valid_from), CONSTRAINT ck_stop_factor_metric_params_is_array CHECK (jsonb_typeof(params) = 'array'), CONSTRAINT ck_stop_factor_metric_calculator CHECK (calculator IN ( 'OVERDUE_BUCKET_COUNT', 'RESTRUCTURING_COUNT', 'BUREAU_REQUESTS_COUNT', 'NEW_CREDITS_COUNT', 'KIB_REFUSAL_STATUSES', 'KIB_ACTIVE_DISPUTES', 'KIB_UNJUSTIFIED_DISPUTES', 'CURRENT_OVERDUE_DAYS', 'CURRENT_OVERDUE_AMOUNT', 'OPEN_CREDITS_COUNT')) );
CREATE UNIQUE INDEX ux_stop_factor_metric_current_version ON stop_factors.stop_factor_metric ((COALESCE(root_id, id))) WHERE valid_to IS NULL; CREATE UNIQUE INDEX ux_stop_factor_metric_version_number ON stop_factors.stop_factor_metric ((COALESCE(root_id, id)), version_number); CREATE UNIQUE INDEX ux_stop_factor_metric_current_title ON stop_factors.stop_factor_metric (title) WHERE valid_to IS NULL; CREATE INDEX idx_stop_factor_metric_root_id ON stop_factors.stop_factor_metric (root_id);
CREATE SEQUENCE public.stop_factor_metric_id_generator START WITH 1 INCREMENT BY 1;

-- Legacy stop factor N becomes group N with the single stop factor N (1.3.4),
-- so conditions and checks keep their stop_factor_id
ALTER TABLE stop_factors.stop_factor RENAME TO stop_factor_group;

ALTER TABLE stop_factors.stop_factor_group
    ADD COLUMN root_id        BIGINT,
    ADD COLUMN version_number INTEGER NOT NULL DEFAULT 1,
    ADD COLUMN valid_from     TIMESTAMP(6),
    ADD COLUMN valid_to       TIMESTAMP(6),
    ADD COLUMN change_reason  VARCHAR(255),
    ADD COLUMN created_by     VARCHAR(255);

UPDATE stop_factors.stop_factor_group
SET valid_from = COALESCE(created_date, now()),
    created_by = 'migration';

ALTER TABLE stop_factors.stop_factor_group
    ALTER COLUMN valid_from SET NOT NULL,
    ADD CONSTRAINT fk_stop_factor_group_root FOREIGN KEY (root_id) REFERENCES stop_factors.stop_factor_group (id),
    ADD CONSTRAINT ck_stop_factor_group_root CHECK ((root_id IS NULL) = (version_number = 1)),
    ADD CONSTRAINT ck_stop_factor_group_version_number CHECK (version_number >= 1),
    ADD CONSTRAINT ck_stop_factor_group_validity CHECK (valid_to IS NULL OR valid_to >= valid_from);

CREATE UNIQUE INDEX ux_stop_factor_group_current_version
    ON stop_factors.stop_factor_group ((COALESCE(root_id, id))) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX ux_stop_factor_group_version_number
    ON stop_factors.stop_factor_group ((COALESCE(root_id, id)), version_number);
CREATE INDEX idx_stop_factor_group_root_id ON stop_factors.stop_factor_group (root_id);

CREATE SEQUENCE public.stop_factor_group_id_generator START WITH 1 INCREMENT BY 1;
SELECT setval('public.stop_factor_group_id_generator',
              (SELECT COALESCE(max(id), 0) + 1 FROM stop_factors.stop_factor_group), false);

rollback.sql:
DROP SEQUENCE public.stop_factor_group_id_generator;

DROP INDEX stop_factors.idx_stop_factor_group_root_id;
DROP INDEX stop_factors.ux_stop_factor_group_version_number;
DROP INDEX stop_factors.ux_stop_factor_group_current_version;

ALTER TABLE stop_factors.stop_factor_group
    DROP CONSTRAINT ck_stop_factor_group_validity,
    DROP CONSTRAINT ck_stop_factor_group_version_number,
    DROP CONSTRAINT ck_stop_factor_group_root,
    DROP CONSTRAINT fk_stop_factor_group_root,
    DROP COLUMN created_by,
    DROP COLUMN change_reason,
    DROP COLUMN valid_to,
    DROP COLUMN valid_from,
    DROP COLUMN version_number,
    DROP COLUMN root_id;

ALTER TABLE stop_factors.stop_factor_group RENAME CONSTRAINT pk_stop_factor_group TO stop_factor_pkey;
ALTER TABLE stop_factors.stop_factor_group RENAME TO stop_factor;

changeSet.sql:
CREATE TABLE stop_factors.stop_factor ( id BIGINT NOT NULL, created_date TIMESTAMP(6), updated_date TIMESTAMP(6), group_id BIGINT NOT NULL, metric_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, order_number INTEGER NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, params JSONB NOT NULL DEFAULT '{}'::jsonb, segment VARCHAR(32), CONSTRAINT pk_stop_factor PRIMARY KEY (id), CONSTRAINT fk_stop_factor_group FOREIGN KEY (group_id) REFERENCES stop_factors.stop_factor_group (id), CONSTRAINT fk_stop_factor_metric FOREIGN KEY (metric_id) REFERENCES stop_factors.stop_factor_metric (id), CONSTRAINT uq_stop_factor_order UNIQUE (group_id, order_number), CONSTRAINT ck_stop_factor_params_is_object CHECK (jsonb_typeof(params) = 'object'), CONSTRAINT ck_stop_factor_segment CHECK (segment IS NULL OR segment IN ('RETAIL', 'MSB')) );
CREATE INDEX idx_stop_factor_group_id ON stop_factors.stop_factor (group_id); CREATE INDEX idx_stop_factor_metric_id ON stop_factors.stop_factor (metric_id);
-- Legacy stop factor -> metric and params; one missing here fails NOT NULL metric_id INSERT INTO stop_factors.stop_factor (id, created_date, group_id, metric_id, name, order_number, is_active, params) SELECT g.id, g.created_date, g.id, m.metric_id, g.name, 1, g.is_active, m.params::jsonb FROM stop_factors.stop_factor_group g LEFT JOIN (VALUES ( 1, 1, '{}'), ( 2, 2, '{}'), ( 3, 3, '{}'), ( 4, 4, '{"source": "KIB", "periodFromMonth": 1, "periodToMonth": 12}'), ( 5, 4, '{"source": "OB", "periodFromMonth": 1, "periodToMonth": 12}'), ( 6, 4, '{"source": "KIB", "periodFromMonth": 13, "periodToMonth": 24}'), ( 7, 4, '{"source": "OB", "periodFromMonth": 13, "periodToMonth": 24}'), ( 8, 5, '{"days": 7}'), ( 9, 6, '{}'), (10, 7, '{}'), (11, 8, '{"days": 30}'), (12, 9, '{}'), (13, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 1, "maxOverdueDays": 7}'), (14, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 8}'), (15, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 1, "maxOverdueDays": 7}'), (16, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 8}'), (17, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 1, "maxOverdueDays": 10}'), (18, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 11, "maxOverdueDays": 20}'), (19, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 15}'), (20, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 1, "maxOverdueDays": 10}'), (21, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 11, "maxOverdueDays": 20}'), (22, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 21, "maxOverdueDays": 30}'), (23, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 31}'), (24, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 1, "maxOverdueDays": 60}'), (25, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 61, "maxOverdueDays": 90}'), (26, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 91}'), (27, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 1, "maxOverdueDays": 15}'), (28, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 16, "maxOverdueDays": 30}'), (29, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 31}'), (30, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 1, "maxOverdueDays": 15}'), (31, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 16, "maxOverdueDays": 30}'), (32, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 31}'), (33, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 21, "maxOverdueDays": 30}'), (34, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 31}') ) AS m (stop_factor_id, metric_id, params) ON m.stop_factor_id = g.id;
SELECT setval('public.stop_factor_id_generator', (SELECT COALESCE(max(id), 0) + 1 FROM stop_factors.stop_factor), false);
ALTER TABLE stop_factors.stop_factor_group DROP COLUMN name;

rollback.sql:
ALTER TABLE stop_factors.stop_factor_group ADD COLUMN name VARCHAR(255);

UPDATE stop_factors.stop_factor_group g
SET name = f.name
FROM stop_factors.stop_factor f
WHERE f.id = g.id;

ALTER TABLE stop_factors.stop_factor_group ALTER COLUMN name SET NOT NULL;

DROP TABLE stop_factors.stop_factor;

changeSet.sql:
ALTER TABLE stop_factors.stop_factor_condition ADD CONSTRAINT fk_stop_factor_condition_stop_factor FOREIGN KEY (stop_factor_id) REFERENCES stop_factors.stop_factor (id), ADD COLUMN operator VARCHAR(16), ADD COLUMN value_to TEXT;
-- Legacy conditions fire on x > value (IN for statuses); -- an UNDERWRITER threshold below the REJECTED one becomes the RANGE up to it UPDATE stop_factors.stop_factor_condition SET operator = CASE WHEN value_type IN ('ARRAY', 'STRING') THEN 'IN' ELSE 'GT' END;
UPDATE stop_factors.stop_factor_condition uw SET operator = 'RANGE', value_to = rej.value FROM stop_factors.stop_factor_condition rej WHERE uw.result = 'UNDERWRITER' AND rej.result = 'REJECTED' AND rej.stop_factor_id = uw.stop_factor_id AND uw.value_type IN ('INTEGER', 'DOUBLE') AND rej.value_type IN ('INTEGER', 'DOUBLE') AND rej.value::numeric > uw.value::numeric;
ALTER TABLE stop_factors.stop_factor_condition ALTER COLUMN operator SET NOT NULL, ALTER COLUMN result SET NOT NULL, ADD CONSTRAINT ck_stop_factor_condition_result CHECK (result IN ('REJECTED', 'UNDERWRITER')), ADD CONSTRAINT ck_stop_factor_condition_operator CHECK ( CASE WHEN value_type IN ('ARRAY', 'STRING') THEN operator = 'IN' ELSE operator IN ('GT', 'GTE', 'LT', 'LTE', 'EQ', 'RANGE', 'BETWEEN') END), ADD CONSTRAINT ck_stop_factor_condition_value_to CHECK ( CASE WHEN operator IN ('RANGE', 'BETWEEN') THEN value_to IS NOT NULL AND value_to::numeric > value::numeric ELSE value_to IS NULL END);

ALTER TABLE stop_factors.stop_factor_check
    ADD CONSTRAINT fk_stop_factor_check_stop_factor
        FOREIGN KEY (stop_factor_id) REFERENCES stop_factors.stop_factor (id),
    ADD COLUMN product_id BIGINT,
    ADD CONSTRAINT fk_stop_factor_check_product FOREIGN KEY (product_id) REFERENCES public.product (id);

CREATE INDEX idx_stop_factor_check_stop_factor_id ON stop_factors.stop_factor_check (stop_factor_id);

CREATE TABLE stop_factors.stop_factor_product (
    stop_factor_id BIGINT NOT NULL,
    product_id     BIGINT NOT NULL,
    CONSTRAINT pk_stop_factor_product PRIMARY KEY (stop_factor_id, product_id),
    CONSTRAINT fk_stop_factor_product_stop_factor
        FOREIGN KEY (stop_factor_id) REFERENCES stop_factors.stop_factor (id),
    CONSTRAINT fk_stop_factor_product_product FOREIGN KEY (product_id) REFERENCES public.product (id)
);

CREATE INDEX idx_stop_factor_product_product_id ON stop_factors.stop_factor_product (product_id);
